import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            if (n > 11) {
                out.println("0");
                return;
            }
            int[][] pts = new int[n][5];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 5; j++) {
                    pts[i][j] = in.nextInt();
                }
            }
            ArrayList<Integer> good = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                boolean ok = true;
                for (int j = 0; j < n && ok; j++) {
                    for (int k = 0; k < n && ok; k++) {
                        if (i != j && i != k && j != k) {
                            int[] one = pts[j];
                            int[] two = pts[k];
                            int[] three = pts[i];
                            int[] v1 = new int[5];
                            int[] v2 = new int[5];
                            for (int d = 0; d < 5; d++) {
                                v1[d] = one[d] - three[d];
                                v2[d] = two[d] - three[d];
                            }
                            if (angle(v1, v2)) {
                                ok = false;
                            }
                        }
                    }
                }
                if (ok) good.add(i + 1);
            }
            if (good.isEmpty()) {
                out.println("0");
            } else {
                out.println(good.size());
                for (int idx : good) out.println(idx);
            }
        }

        static boolean angle(int[] a, int[] b) {
            double dot = 0;
            for (int d = 0; d < 5; d++) dot += a[d] * b[d];
            double amag = mag(a);
            double bmag = mag(b);
            double ang = Math.toDegrees(Math.acos(dot / (amag * bmag)));
            return ang < 90;
        }

        static double mag(int[] a) {
            double s = 0;
            for (int d = 0; d < 5; d++) s += a[d] * a[d];
            return Math.sqrt(s);
        }
    }

    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;
        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
    }
}
